// Notchset date-range-picker 2.0.0 · https://notchset.dev/changelog
"use client";
import * as React from "react";
import { Popover } from "@base-ui/react/popover";
import { CalendarRange } from "lucide-react";
import { cn } from "@/lib/utils";
import { Calendar, type Range } from "@/components/ui/notchset/calendar";
import { DEFAULT_LOCALE, type Day, formatRange, today as todayOf } from "@/lib/notchset/dates";
import { shortcutItem } from "@/components/ui/notchset/date-picker";
import { popupPositioner, popupSurface } from "@/lib/notchset/popup";
import { useReturnFocus } from "@/lib/notchset/return-focus";
import { usePortalContainer } from "@/lib/notchset/portal";

/*
 * Date range picker: a report's period. Presets first (This quarter, Last quarter, This year), each with its
 * dates written out; or press a start and an end on the calendar, with the days between washed as you hover.
 * The trigger says the range in words ("Oct 1 – Dec 31") or the preset's name; dates you picked yourself show in
 * the list as a ticked Custom row. Esc mid-pick keeps the old range.
 */
type Preset = { label: string; start: Day; end: Day };
type DateRange = { start: Day; end: Day };
type DateRangePickerProps = {
  value: DateRange | null;
  onValueChange: (value: DateRange) => void;
  presets?: Preset[] | undefined;
  "aria-label"?: string | undefined;
  placeholder?: string | undefined;
  min?: Day | undefined;
  max?: Day | undefined;
  /** BCP 47 locale for every date and time label; fixed so server and client render the same. Default "en-US". */
  locale?: string | undefined;
  today?: Day | undefined;
  className?: string | undefined;
};

/** a range is allowed when it runs forward and sits wholly inside min/max */
const validRange = (r: { start: Day; end: Day }, min?: Day, max?: Day) => r.start <= r.end && !(min && r.start < min) && !(max && r.end > max);

function DateRangePicker({ value, onValueChange, presets = [], placeholder = "Pick dates", min, max, locale = DEFAULT_LOCALE, today, className, ...aria }: DateRangePickerProps) {
  const portalContainer = usePortalContainer();
  const now = today ?? todayOf();
  const [open, setOpen] = React.useState(false);
  const returnFocus = useReturnFocus();
  const preset = value && presets.find((p) => p.start === value.start && p.end === value.end);
  const done = (r: DateRange) => {
    if (!validRange(r, min, max)) return;
    onValueChange(r);
    setOpen(false);
  };
  return (
    <Popover.Root open={open} onOpenChange={(o) => setOpen(o)}>
      <Popover.Trigger
        data-slot="date-range-picker"
        {...aria}
        className={cn(
          "inline-flex h-[var(--ns-control-sm)] cursor-pointer items-center gap-1.5 rounded-[var(--ns-radius)] bg-[var(--ns-raised)] px-2.5 text-[length:var(--ns-text-body)] font-[number:var(--ns-weight-medium)] text-[var(--ns-ink)] shadow-[var(--ns-bezel)] outline-hidden hover:bg-[var(--ns-hover)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--ns-signal)] pointer-coarse:h-9 max-[960px]:h-9 [&_svg]:size-3.5 [&_svg]:text-[var(--ns-ink-3)]",
          className,
        )}
      >
        <CalendarRange />
        {value ? (
          <span className="tabular-nums">
            {preset ? <>{preset.label} <span className="ml-1 font-[number:var(--ns-weight-regular)] text-[var(--ns-ink-3)]">{formatRange(value.start, value.end, locale)}</span></> : formatRange(value.start, value.end, locale)}
          </span>
        ) : (
          <span className="text-[var(--ns-ink-3)]">{placeholder}</span>
        )}
      </Popover.Trigger>
      <Popover.Portal container={portalContainer}>
        <Popover.Positioner sideOffset={4} collisionPadding={8} align="end" className={popupPositioner}>
          <Popover.Popup data-slot="date-range-popup" data-ns-layer="" data-ns-moves="" finalFocus={returnFocus} className={cn(popupSurface, "flex gap-2 p-2 max-[600px]:flex-col")}>
            <Popover.Title className="sr-only">{aria["aria-label"] ?? "Pick a date range"}</Popover.Title>
            <RangeBody locale={locale} key={value ? `${value.start}:${value.end}` : "none"} value={value} presets={presets} now={now} min={min} max={max} onDone={done} />
          </Popover.Popup>
        </Popover.Positioner>
      </Popover.Portal>
    </Popover.Root>
  );
}

function RangeBody({ locale, value, presets, now, min, max, onDone }: { locale: string; value: DateRange | null; presets: Preset[]; now: Day; min?: Day | undefined; max?: Day | undefined; onDone: (r: DateRange) => void }) {
  const [draft, setDraft] = React.useState<Range>(value ?? { start: null, end: null });
  return (
    <>
      {presets.length > 0 && (
        <>
          <div className="flex w-[200px] shrink-0 flex-col gap-0.5 max-[600px]:w-full">
            {presets.map((p) => (
              <button key={p.label} type="button" disabled={!validRange(p, min, max)} aria-pressed={value?.start === p.start && value?.end === p.end} onClick={() => onDone({ start: p.start, end: p.end })} className={cn(shortcutItem, "py-1.5 disabled:opacity-45")}>
                <span className="flex min-w-0 flex-col gap-px">
                  <span className="font-[number:var(--ns-weight-medium)]">{p.label}</span>
                  <span className="text-[length:var(--ns-text-meta)] text-[var(--ns-ink-3)] tabular-nums">{formatRange(p.start, p.end, locale)}</span>
                </span>
              </button>
            ))}
            {value && !presets.some((p) => p.start === value.start && p.end === value.end) && (
              // your own dates show as a ticked Custom row, so it is clear you are not on a preset
              <div aria-current="true" className={cn(shortcutItem, "cursor-default bg-[var(--ns-selected)] py-1.5 hover:bg-[var(--ns-selected)]")}>
                <span className="flex min-w-0 flex-col gap-px">
                  <span className="font-[number:var(--ns-weight-medium)]">Custom</span>
                  <span className="text-[length:var(--ns-text-meta)] text-[var(--ns-ink-3)] tabular-nums">{formatRange(value.start, value.end, locale)}</span>
                </span>
              </div>
            )}
          </div>
          <div className="w-px shrink-0 self-stretch bg-[var(--ns-line-soft)] max-[600px]:h-px max-[600px]:w-auto" />
        </>
      )}
      <div className="flex flex-col gap-1">
        <Calendar
          range={draft}
          locale={locale}
          today={now}
          min={min}
          max={max}
          onRangeChange={(r) => {
            setDraft(r);
            if (r.start && r.end) onDone({ start: r.start, end: r.end });
          }}
          className="p-1"
        />
        <span aria-live="polite" className="px-1.5 pb-1 text-[length:var(--ns-text-meta)] text-[var(--ns-ink-3)]">
          {draft.start && !draft.end ? "Now pick the last day" : "Pick the first day"}
        </span>
      </div>
    </>
  );
}

export { DateRangePicker, type DateRange, type DateRangePickerProps, type Preset };

// Notchset date-range-picker 2.0.0 · https://notchset.dev/changelog
/*
 * Dates for the pickers, with no date library: a day is an ISO string ("2026-11-07"), so it never shifts with
 * the reader's time zone, compares with < and >, and is what a form stores. Display uses Intl in UTC for the
 * same reason. Times are minutes after midnight.
 */

export type Day = string;

const DAY = 864e5;
const toUTC = (d: Day) => Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10));
export const fromUTC = (t: number): Day => new Date(t).toISOString().slice(0, 10);
export const makeDay = (y: number, m: number, d: number): Day => fromUTC(Date.UTC(y, m, d));
export const partsOf = (d: Day) => ({ y: +d.slice(0, 4), m: +d.slice(5, 7) - 1, d: +d.slice(8, 10) });

/** Today in the reader's own calendar. */
export function today(now = new Date()): Day {
  return makeDay(now.getFullYear(), now.getMonth(), now.getDate());
}

export const addDays = (d: Day, n: number): Day => fromUTC(toUTC(d) + n * DAY);
export function addMonths(d: Day, n: number): Day {
  const { y, m, d: day } = partsOf(d);
  const last = new Date(Date.UTC(y, m + n + 1, 0)).getUTCDate();
  return makeDay(y, m + n, Math.min(day, last));
}
export const weekday = (d: Day) => new Date(toUTC(d)).getUTCDay();
export const sameMonth = (a: Day, b: Day) => a.slice(0, 7) === b.slice(0, 7);
export const daysBetween = (a: Day, b: Day) => Math.round((toUTC(b) - toUTC(a)) / DAY);

/** Six full weeks around a month, so the calendar never changes height as you page through months. */
export function monthGrid(year: number, month: number, weekStartsOn = 1): Day[] {
  const first = makeDay(year, month, 1);
  const lead = (weekday(first) - weekStartsOn + 7) % 7;
  const start = addDays(first, -lead);
  return Array.from({ length: 42 }, (_, i) => addDays(start, i));
}

export const DEFAULT_LOCALE = "en-US";

export function weekdayNames(weekStartsOn = 1, locale = DEFAULT_LOCALE) {
  const f = new Intl.DateTimeFormat(locale, { weekday: "narrow", timeZone: "UTC" });
  const full = new Intl.DateTimeFormat(locale, { weekday: "long", timeZone: "UTC" });
  // 2024-01-07 was a Sunday
  return Array.from({ length: 7 }, (_, i) => {
    const t = Date.UTC(2024, 0, 7 + ((i + weekStartsOn) % 7));
    return { short: f.format(t), long: full.format(t) };
  });
}

export function formatDay(d: Day, style: "short" | "medium" | "long" = "medium", locale = DEFAULT_LOCALE) {
  const opts: Intl.DateTimeFormatOptions =
    style === "short" ? { month: "short", day: "numeric" } : style === "medium" ? { month: "short", day: "numeric", year: "numeric" } : { weekday: "long", month: "long", day: "numeric", year: "numeric" };
  return new Intl.DateTimeFormat(locale, { ...opts, timeZone: "UTC" }).format(toUTC(d));
}
export const monthName = (m: number, style: "long" | "short" = "long", locale = DEFAULT_LOCALE) =>
  new Intl.DateTimeFormat(locale, { month: style, timeZone: "UTC" }).format(Date.UTC(2024, m, 1));

/** "Nov 3 – Dec 31" (one year) or "Nov 3, 2026 – Jan 4, 2027". */
export function formatRange(a: Day, b: Day, locale = DEFAULT_LOCALE) {
  return a.slice(0, 4) === b.slice(0, 4) ? `${formatDay(a, "short", locale)} – ${formatDay(b, "short", locale)}` : `${formatDay(a, "medium", locale)} – ${formatDay(b, "medium", locale)}`;
}

const MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const WEEKDAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
const monthOf = (w: string) => (w.length >= 3 ? MONTHS.findIndex((m) => w.startsWith(m)) : -1);
const DAYNAMES = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
const weekdayOf = (w: string) => (w.length >= 3 ? DAYNAMES.findIndex((d, i) => d.startsWith(w) || (WEEKDAYS[i] === w.slice(0, 3) && /^(tues?|thur?s?|weds?)$/.test(w))) : -1);

/**
 * A typed date: "today", "tomorrow", "yesterday", "fri", "next fri", "in 2 weeks", "3 days ago",
 * "nov 3", "3 nov", "nov 3 2023", "3 November, 2023", "2023-11-03". Numeric dates like 11/03 are refused:
 * half the world reads them the other way round. A month and day with no year means this year; with `ahead`
 * (a close date, a due date: things still to come) it means the next time that date comes round, never the past.
 */
export function parseDay(text: string, now: Day = today(), opts: { ahead?: boolean } = {}): Day | null {
  /* typed digits are unbounded: a result outside the supported years (or a date the engine cannot build) is no date */
  try {
    const out = parseDayRaw(text, now, opts);
    return out && inRange(out) ? out : null;
  } catch {
    return null;
  }
}
const inRange = (d: Day) => /^\d{4}-\d{2}-\d{2}$/.test(d) && +d.slice(0, 4) >= MIN_YEAR;
const MIN_YEAR = 1000;

function parseDayRaw(text: string, now: Day, { ahead = false }: { ahead?: boolean }): Day | null {
  const s = text.trim().toLowerCase().replace(/,/g, " ").replace(/\s+/g, " ");
  if (!s) return null;
  if (s === "today" || s === "now") return now;
  if (s === "tomorrow" || s === "tmr" || s === "tmrw") return addDays(now, 1);
  if (s === "yesterday") return addDays(now, -1);
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return valid(+m[1]!, +m[2]! - 1, +m[3]!);
  m = s.match(/^in (\d+) (day|week|month|year)s?$/) ?? s.match(/^(\d+) (day|week|month|year)s? from now$/);
  if (m) return shift(now, +m[1]!, m[2]!);
  m = s.match(/^(\d+) (day|week|month|year)s? ago$/);
  if (m) return shift(now, -m[1]!, m[2]!);
  m = s.match(/^(next |this )?([a-z]+)$/);
  if (m && weekdayOf(m[2]!) >= 0 && monthOf(m[2]!) < 0) {
    // "fri" and "next fri" both mean the coming Friday, 1 to 7 days ahead; the field shows the date before Enter
    return addDays(now, (weekdayOf(m[2]!) - weekday(now) + 7) % 7 || 7);
  }
  const words = s.split(" ");
  let month = -1, day = -1, year = -1;
  for (const w of words) {
    if (/^\d{4}$/.test(w)) year = +w;
    else if (/^\d{1,2}(st|nd|rd|th)?$/.test(w)) day = parseInt(w, 10);
    else if (monthOf(w) >= 0) month = monthOf(w);
    else return null;
  }
  if (month < 0 || day < 0) return null;
  if (year >= 0) return valid(year, month, day);
  const y = partsOf(now).y;
  if (!ahead) return valid(y, month, day);
  /* the next time it comes round: a leap day can be up to eight years off (2096 → 2104); a date no year has stays null */
  for (let k = 0; k <= 8; k++) {
    const out = valid(y + k, month, day);
    if (out && out >= now) return out;
  }
  return null;
}

function valid(y: number, m: number, d: number): Day | null {
  if (m < 0 || m > 11 || d < 1 || y < MIN_YEAR || y > 9999) return null;
  const out = makeDay(y, m, d);
  return partsOf(out).m === m ? out : null;
}
function shift(d: Day, n: number, unit: string): Day {
  return unit === "day" ? addDays(d, n) : unit === "week" ? addDays(d, 7 * n) : unit === "month" ? addMonths(d, n) : addMonths(d, 12 * n);
}

/** A typed time: "2:30pm", "2.30 pm", "14:30", "1430", "2p", "9", "noon", "midnight". Minutes after midnight. */
export function parseTime(text: string): number | null {
  const s = text.trim().toLowerCase().replace(/\s+/g, "");
  if (s === "noon") return 720;
  if (s === "midnight") return 0;
  const m = s.match(/^(\d{1,2})(?:[:.]?(\d{2}))?(a|am|p|pm)?$/);
  if (!m) return null;
  let h = +m[1]!;
  const min = m[2] ? +m[2] : 0;
  if (min > 59) return null;
  if (m[3]) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (m[3].startsWith("p") ? 12 : 0);
  } else if (h > 23) return null;
  return h * 60 + min;
}

export function formatTime(minutes: number, hour12: boolean, locale = DEFAULT_LOCALE) {
  return new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit", hour12, timeZone: "UTC" }).format(Date.UTC(2024, 0, 1, 0, minutes));
}

// Notchset date-range-picker 2.0.0 · https://notchset.dev/changelog
/*
 * The one popup surface every list that opens from a control uses (select, combobox, recipient picker, and
 * menus in batch 3): the prototype's .menu. It drops just below its control, and on a phone it becomes a
 * bottom sheet with a grab handle and finger-sized rows. Kept as class strings so each primitive's own parts
 * wear the same look.
 */

/** On the Positioner: above everything but dialogs; on a phone, pinned to the bottom edge as a sheet (above a tab bar
    when the app sets --ns-sheet-bottom to its height). */
export const popupPositioner =
  "z-50 outline-hidden max-[600px]:!fixed max-[600px]:!inset-x-2 max-[600px]:!top-auto max-[600px]:!bottom-[calc(var(--ns-sheet-bottom)+env(safe-area-inset-bottom,0px))] max-[600px]:!left-2 max-[600px]:!w-auto max-[600px]:!transform-none";

/** On the Popup. */
export const popupSurface =
  "min-w-[max(var(--anchor-width,0px),180px)] max-h-[min(420px,70vh,var(--available-height,70vh))] overflow-auto overscroll-contain rounded-[var(--ns-radius-lg)] bg-[var(--ns-raised)] p-[5px] text-[length:var(--ns-text-body)] text-[var(--ns-ink)] shadow-[0_0_0_1px_var(--ns-line),var(--ns-shadow-float)] outline-hidden origin-[var(--transform-origin)] " +
  "[animation:ns-menu-in_var(--ns-time-menu)_var(--ns-ease)] data-ending-style:opacity-0 data-ending-style:[transition:opacity_110ms_ease] " +
  "max-[600px]:w-auto max-[600px]:min-w-0 max-[600px]:max-h-[70dvh] max-[600px]:rounded-[var(--ns-radius-xl)] max-[600px]:px-1.5 max-[600px]:pt-3.5 max-[600px]:pb-1.5 max-[600px]:[animation:ns-sheet-up_var(--ns-time-panel)_var(--ns-ease-panel)] " +
  "max-[600px]:before:absolute max-[600px]:before:top-[5px] max-[600px]:before:left-1/2 max-[600px]:before:h-1 max-[600px]:before:w-9 max-[600px]:before:-translate-x-1/2 max-[600px]:before:rounded-full max-[600px]:before:bg-[var(--ns-line)] max-[600px]:before:content-['']";

/** On each item. Highlight (pointer or arrow keys) is the hover wash; the chosen item carries a check. */
export const popupItem =
  "flex w-full min-h-[var(--ns-menu-row)] cursor-default items-center gap-[9px] rounded-[7px] px-[9px] text-left outline-hidden select-none data-highlighted:bg-[var(--ns-hover)] data-disabled:opacity-45 [&_svg:not([data-slot=company-mark])]:size-3.5 [&_svg]:shrink-0";

/** The quiet line a list shows when nothing matches. */
export const popupEmpty = "px-[9px] py-2 text-[length:var(--ns-text-small)] text-[var(--ns-ink-3)] empty:hidden";

// Notchset date-range-picker 2.0.0 · https://notchset.dev/changelog
import * as React from "react";

/*
 * Where overlays (dialogs, menus, popovers, tooltips, toasts, sheets) portal to. By default the document body; a
 * host that themes or scopes a region (a preview stage, a shadow root, a tile in another theme) wraps it in
 * PortalContainer with an element inside that scope, so its overlays keep the region's roles and light or dark.
 */
const PortalContainerContext = React.createContext<HTMLElement | null>(null);

const PortalContainer = PortalContainerContext.Provider;

/** The element overlays portal into here, or undefined for the document body. */
function usePortalContainer(): HTMLElement | undefined {
  return React.useContext(PortalContainerContext) ?? undefined;
}

export { PortalContainer, PortalContainerContext, usePortalContainer };

// Notchset date-range-picker 2.0.0 · https://notchset.dev/changelog
"use client";
import * as React from "react";

/*
 * Focus goes back to whatever opened a layer when it closes, even when the layer is opened from state (a menu
 * item, a shortcut, a row) rather than its own trigger. One document listener remembers the last control
 * focused or pressed outside any layer (marked data-ns-layer); pressing counts too because Safari does not focus
 * a clicked button. Pass the result to a Base UI Popup's finalFocus.
 */
let last: HTMLElement | null = null;
let watching = false;

function watch() {
  if (watching || typeof document === "undefined") return;
  watching = true;
  const note = (e: Event) => {
    const t = e.target as HTMLElement | null;
    if (!t?.closest || t.closest("[data-ns-layer]")) return;
    /* a table row that opens on press is its own opener: it takes focus back (as a J/K row does), so closing
       what it opened never leaves focus on the page's body, where the next Tab can leave the app */
    const row = t.closest<HTMLElement>("tr[data-row]");
    const ctl = t.closest<HTMLElement>("button,a[href],input,select,textarea,[tabindex]");
    if (row && (!ctl || !row.contains(ctl)) && !row.hasAttribute("tabindex")) row.tabIndex = -1;
    last = (row && (!ctl || !row.contains(ctl)) ? row : ctl) ?? last;
  };
  document.addEventListener("focusin", note, true);
  document.addEventListener("pointerdown", note, true);
}

export function useReturnFocus() {
  React.useEffect(watch, []);
  return React.useCallback(() => (last && last.isConnected ? last : true), []);
}
